using HRIS.Api.DTOs.Declaration; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/declarations")][Authorize] public class DeclarationsController:ControllerBase { private readonly IDeclarationService _service; public DeclarationsController(IDeclarationService service)=>_service=service; [HttpGet("templates")] public async Task<IActionResult> Templates([FromQuery]bool includeInactive=false)=>Ok(await _service.GetTemplatesAsync(includeInactive)); [HttpPost("templates")][Authorize(Roles="HR,Support")] public async Task<IActionResult> CreateTemplate(DeclarationTemplateCreateDto dto)=>Ok(await _service.SaveTemplateAsync(0,dto,User.ToUserContext())); [HttpPut("templates/{id:int}")][Authorize(Roles="HR,Support")] public async Task<IActionResult> UpdateTemplate(int id,DeclarationTemplateCreateDto dto)=>Ok(await _service.SaveTemplateAsync(id,dto,User.ToUserContext())); [HttpGet("submissions")] public async Task<IActionResult> Submissions()=>Ok(await _service.GetSubmissionsAsync(User.ToUserContext())); [HttpPost("submit")] public async Task<IActionResult> Submit([FromQuery]int templateId,[FromQuery]int? documentId)=>Ok(await _service.SubmitAsync(templateId,documentId,User.ToUserContext())); }
